// Client-side post search. The index is generated by Jekyll at /search.json.
(() => {
  const form = document.getElementById('search-form');
  const input = document.getElementById('search-input');
  const status = document.getElementById('search-status');
  const list = document.getElementById('post-list');
  if (!form || !input || !status || !list) return;

  const original = Array.from(list.children);
  let index = null;
  let failed = false;

  // The intro stagger is a one-time load effect; don't replay it for results.
  const endIntro = () => list.classList.remove('post-list--intro');
  const introTimer = setTimeout(endIntro, 2200);

  const load = async () => {
    if (index || failed) return;
    try {
      const response = await fetch(form.dataset.index);
      if (!response.ok) throw new Error(String(response.status));
      index = await response.json();
    } catch {
      failed = true;
    }
  };

  const setStatus = (message) => { status.textContent = message; };
  const normalize = (value) => String(value || '').toLowerCase();

  const score = (post, query) => {
    const title = normalize(post.title);
    const description = normalize(post.description);
    const tags = normalize(post.tags);
    const content = normalize(post.content);
    const haystack = `${title} ${description} ${tags} ${content}`;

    const terms = query.split(/\s+/).filter(Boolean);
    if (!terms.every((term) => haystack.includes(term))) return 0;

    let value = 0;
    if (title === query) value += 20;
    if (title.startsWith(query)) value += 8;
    if (title.includes(query)) value += 6;
    if (tags.includes(query)) value += 4;
    if (description.includes(query)) value += 3;
    if (content.includes(query)) value += 1;
    return value;
  };

  const createItem = (post) => {
    const item = document.createElement('li');
    const time = document.createElement('time');
    time.dateTime = post.datetime;
    time.textContent = post.date;

    const heading = document.createElement('h3');
    const link = document.createElement('a');
    link.href = post.url;
    link.textContent = post.title;
    heading.appendChild(link);

    item.append(time, heading);
    return item;
  };

  const update = async () => {
    const query = normalize(input.value.trim());

    if (!query) {
      list.replaceChildren(...original);
      setStatus('');
      return;
    }

    await load();
    if (failed) {
      setStatus('Search is unavailable right now.');
      return;
    }

    clearTimeout(introTimer);
    endIntro();

    const results = index
      .map((post) => ({ post, rank: score(post, query) }))
      .filter((entry) => entry.rank > 0)
      .sort((a, b) => b.rank - a.rank || (a.post.datetime < b.post.datetime ? 1 : -1));

    if (results.length === 0) {
      list.replaceChildren();
      setStatus(`No posts found for \u201c${input.value.trim()}\u201d.`);
      return;
    }

    list.replaceChildren(...results.map((entry) => createItem(entry.post)));
    setStatus(`${results.length} ${results.length === 1 ? 'post' : 'posts'} found.`);
  };

  let timer;
  input.addEventListener('input', () => {
    clearTimeout(timer);
    timer = setTimeout(update, 150);
  });

  form.addEventListener('submit', (event) => {
    event.preventDefault();
    clearTimeout(timer);
    update();
  });

  input.addEventListener('keydown', (event) => {
    if (event.key === 'Escape') {
      input.value = '';
      update();
    }
  });

  const initial = new URLSearchParams(window.location.search).get('q');
  if (initial) {
    input.value = initial;
    update();
  }
})();
